    name: &str,
    reason: &str,
    noun: &str,
    failed: &mut Vec<(String, String)>,
    consecutive: &mut u32,
) -> bool {
    *consecutive += 1;
    tracing::warn!("{name}: MusicBrainz unavailable ({reason}); {noun} skipped");
    failed.push((name.to_string(), reason.to_string()));
    *consecutive >= DISCOVER_PROVIDER_FAILURE_LIMIT
}

