/// Reject a label search page that cannot be trusted.
///
/// The two rejections are deliberately different. A payload shorter than the
/// reported total is *truncation*, not inconsistency: MusicBrainz reports every
/// match while `limit` caps the page, so a broad name such as `Records` arrives as
/// `count = 600, len = 100`. That name is too wide to resolve safely, so it is
/// refused as unresolved with the count and the escape hatch - the alternative,
/// calling it inconsistent, would blame the provider for a name the operator can
/// narrow or pin. A payload *longer* than the reported total is impossible and
/// remains an inconsistent response.
fn check_label_page(label: &str, page: &LabelPage) -> std::result::Result<(), DiscographyError> {
    if page.offset != 0 {
        return Err(DiscographyError::IncompletePagination(format!(
            "label search returned a non-zero offset {}",
            page.offset
        )));
    }
    if page.count > page.labels.len() {
        return Err(DiscographyError::LabelUnresolved(format!(
            "label search for {label:?} matched {} labels ({} shown); use a more specific name \
             or pin discography.label_mbids",
            page.count,
            page.labels.len()
        )));
    }
    if page.count < page.labels.len() {
        return Err(DiscographyError::LabelSearchInconsistent(format!(
            "label search returned {} candidates but reported {}",
            page.labels.len(),
            page.count
        )));
    }
    Ok(())
}

