        &config,
        &db,
        &[label_request("Hospital Records")],
        None,
        None,
        false,
        staging.path(),
        &provider,
    )
    .await
    .expect("a replayed failure is reported, not fatal");

    assert!(
        client.search_queries.lock().unwrap().is_empty(),
